window.PAGES = window.PAGES || []; window.PAGES.push({"slug": "analytical-language-analogy", "title": "วิชา 1 · เชิงภาษา — อุปมาอุปไมยเชิงภาษา", "subject": "analytical", "order": 13, "exam_topics": ["language"], "html": "<h1>วิชา 1 · เชิงภาษา — อุปมาอุปไมยเชิงภาษา</h1>\n<h2>เป้าหมายการเรียนรู้และแนวโน้ม</h2>\n<ul><li>ระบุความสัมพันธ์ระหว่างคำคู่หนึ่ง แล้วหาคู่ที่มีความสัมพันธ์เดียวกัน</li><li>แยกแยะความสัมพันธ์: คำตรงข้าม, ส่วนประกอบ, หน้าที่, ตัวอย่างของกลุ่ม, วัตถุ-วัสดุ, ผู้ทำ-สิ่งที่ทำ, เหตุ-ผล, สัญลักษณ์</li></ul>\n<p><strong>แนวโน้มที่ออกสอบ</strong>: คำคู่กับคำคู่ \"A-B : C-?\" ตอบด้วยสี่ตัวเลือก — ภาษาสมัยใหม่ผสมศัพท์ราชการ</p>\n<h2>แนวคิดหลักจากศูนย์</h2>\n<p><strong>อุปมาอุปไมย (analogy)</strong> คือการเปรียบเทียบความสัมพันธ์ ไม่ใช่เปรียบเทียบคำ — ต้องหา \"ความสัมพันธ์\" ของคู่แรกก่อนเสมอ แล้วจึงหาคู่ที่มีความสัมพันธ์แบบเดียวกัน</p>\n<p><strong>ประเภทความสัมพันธ์ที่สอบบ่อย</strong></p>\n<div class=\"table-wrap\"><table><thead><tr><th>ประเภท</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>คำตรงข้าม</td><td>ดำ : ขาว</td></tr><tr><td>ส่วน-องค์ประกอบ</td><td>มือ : นิ้ว · ต้นไม้ : ใบ</td></tr><tr><td>ผู้ทำ-สิ่งที่ทำ</td><td>ชาวนา : นา · ครู : สอน</td></tr><tr><td>วัตถุ-วัสดุ</td><td>เก้าอี้ : ไม้ · เสื้อ : ผ้า</td></tr><tr><td>สิ่ง-หน้าที่</td><td>นาฬิกา : บอกเวลา · แว่นตา : มอง</td></tr><tr><td>ตัวอย่างของกลุ่ม</td><td>กุหลาบ : ดอกไม้ · ข้าว : ธัญพืช</td></tr><tr><td>เกี่ยวข้องกัน</td><td>เข็ม : ด้าย · ปากกา : หมึก</td></tr><tr><td>เหตุ-ผล</td><td>ฝน : น้ำท่วม · แบคทีเรีย : โรค</td></tr><tr><td>สัญลักษณ์</td><td>กกต. : เลือกตั้ง · ช้าง : ชาติ</td></tr><tr><td>คำขยายความหมาย</td><td>ไฟ : ความร้อน · น้ำ : ความชุ่มชื้น</td></tr></tbody></table></div>\n<h2>กล่องหลักการ</h2>\n<div class=\"formula-box\"><div class=\"fb-title\">📌 วิธีทำ 3 ขั้น</div>\n<ol><li><strong>ระบุความสัมพันธ์คู่แรก</strong> — พูดออกมาเป็นประโยค เช่น \"มือ คือ ส่วนประกอบของ นิ้ว\" → ความสัมพันธ์ = ส่วนของ</li><li><strong>ใช้ประโยคเดียวกันกับตัวเลือก</strong> — \"___ คือ ส่วนประกอบของ ___\" ตัวเลือกไหนเข้าได้ ตอบตัวนั้น</li><li><strong>ตรวจทิศทาง</strong> — ซ้ายไปขวา ต้องเหมือนกันทุกคู่ (A→B ไม่ใช่ B→A)</li></ol>\n<h2>4 ตัวอย่าง</h2>\n<h3>ตัวอย่างที่ 1</h3>\n<h3>ตัวอย่างที่ 2</h3>\n<h3>ตัวอย่างที่ 3</h3>\n<h3>ตัวอย่างที่ 4 (ยาก)</h3>\n<h2>กับดักที่พบบ่อย</h2>\n<ol><li>มองหา \"ความเกี่ยวข้องกว้าง ๆ\" แทน \"ความสัมพันธ์ที่แม่นยำ\" — ต้องเป็นประโยคเดียวกันเด๊ะ ๆ</li><li>สลับทิศ — คู่แรก A→B แต่ไปเลือก B→A</li><li>ตัวเลือกที่ \"เกี่ยวข้องแต่ความสัมพันธ์คนละแบบ\" เช่น มือ:นิ้ว (ส่วนของ) vs นิ้ว:มือ (ถูกก็ใช้ได้ถ้าคู่แรกเป็นส่วนของ) — ระมัดระวังทิศ</li><li>คำตอบซ้ำความหมายกับคู่แรก — ไม่มีประโยชน์</li></ol>\n<div class=\"cheat-sheet\">\n<h3>📋 สรุปหน้าเดียว</h3>\n<ol><li>พูดความสัมพันธ์คู่แรกเป็นประโยค</li><li>เติมคำในประโยคเดียวกันกับตัวเลือก</li><li>ตรวจทิศทาง A→B</li><li>ความสัมพันธ์ 10 แบบ: ตรงข้าม/ส่วน/ผู้ทำ-สิ่งทำ/วัสดุ/หน้าที่/กลุ่ม/คู่คำ/เหตุ-ผล/สัญลักษณ์/ขยายความหมาย</li></ol>\n<h2>Quick check</h2>\n<p>ฝึกข้อที่เกี่ยวข้อง: <code>#/practice?topic=language</code> (ข้อ S1-LANG-0031 ถึง S1-LANG-0040)</p>"});
